import{_ as i,c as e,o,ae as a}from"./chunks/framework.Dh1jimFm.js";const m=JSON.parse('{"title":"模块化开发","description":"","frontmatter":{"title":"模块化开发","tags":["模块化开发"],"category":[["编程相关","JavaScript"]],"abbrlink":"b96efc28","date":"2019-03-20T14:59:29.000Z"},"headers":[],"relativePath":"docs/old/模块化开发.md","filePath":"docs/old/模块化开发.md"}'),u={name:"docs/old/模块化开发.md"};function r(t,l,d,n,p,s){return o(),e("div",null,l[0]||(l[0]=[a('<h1 id="没有模块化开发的时候" tabindex="-1">没有模块化开发的时候 <a class="header-anchor" href="#没有模块化开发的时候" aria-label="Permalink to &quot;没有模块化开发的时候&quot;">​</a></h1><ul><li>问题： <ol><li>没有办法维护</li><li>全局变量污染</li><li>依赖关系不清</li><li>必须按顺序引入文件</li></ol></li></ul><h1 id="iife-伪模块化标准-2003-2011" tabindex="-1">IIFE 伪模块化标准(2003~2011) <a class="header-anchor" href="#iife-伪模块化标准-2003-2011" aria-label="Permalink to &quot;IIFE 伪模块化标准(2003~2011)&quot;">​</a></h1><ul><li>Immediaitely Invoked Function Expression</li><li>自执行函数<code>(function () {})()</code></li><li>解决问题: <ol><li>依赖不清 <ul><li>直接在自执行函数的参数位置，能看到依赖了哪些模块</li></ul></li><li>变量全局污染 <ul><li>你后面的代码该用什么变量用什么</li></ul></li></ol></li><li>问题: <ol><li>文件顺序不能动</li><li>只能知道我依赖的几个模块，但是模块在哪个文件中不好说</li></ol></li></ul><h1 id="commonjs-模块化标准" tabindex="-1">CommonJS 模块化标准 <a class="header-anchor" href="#commonjs-模块化标准" aria-label="Permalink to &quot;CommonJS 模块化标准&quot;">​</a></h1><ul><li>2009 年，nodejs 出现了</li><li>使用JS去做服务端语言</li><li>伴生的是 CommonJS 模块化标准</li><li>缺点:只能在后端JS里面用</li></ul><h1 id="amd-模块化标准-依赖前置" tabindex="-1">AMD 模块化标准 - 依赖前置 <a class="header-anchor" href="#amd-模块化标准-依赖前置" aria-label="Permalink to &quot;AMD 模块化标准 - 依赖前置&quot;">​</a></h1><ul><li><p>Async Module Definition</p></li><li><p>2011出现的，社区里面发起的</p></li><li><p>因为非官方，没有关键字，大家书写了一套叫做 require.js 的第三方文件</p></li><li><p>来实现模块化标准</p></li><li><p>把每一个js文件独立出来了</p></li><li><p>使用了导入导出的语法来实现模块化</p></li><li><p>在JS文件里面引入另一个JS文件</p></li><li><p>页面只需要引入最后的整合文件就可以了</p></li><li><p>语法：</p><ul><li><p>定义模块(调用define 的方法)</p><ol><li><p>独立模块定义</p><ul><li>每一个模块文件开始执行define()</li><li>我不依赖其他文件，我就是一个单纯的模块</li><li>向外暴露的内容，直接return 出去就好了</li></ul></li><li><p>依赖其他模块的模块(我也是一个模块文件，但是我依赖的以他模块的内容)</p><ul><li>使用define() 定义</li><li>语法: <code>define([ 依赖文件1,依赖文件2, ... ], function (模块A,模块B) {})</code></li></ul></li></ol></li><li><p>导入其他模块</p><ul><li>使用这个方法require()</li><li>语法: <code>require([ 依赖文件1,依赖文件2, ... ], function (模块1, 模块2){})</code></li></ul></li></ul></li><li><p>解决问题:</p><ol><li><p>依赖很清晰</p><ul><li>因为只有一个文件，那么所有的东西都在一个文件里面出现</li></ul></li><li><p>变量全局污染</p><ul><li>没有全局污染，都在私有作用域</li></ul></li></ol></li><li><p>问题:</p><ul><li>依赖前置 <ul><li>不管多少行以后使用的东西，都会在打开页面的时候就加再进来</li><li>缺点：首屏加载时间长</li><li>优点：后期操作流畅</li></ul></li></ul></li></ul><h1 id="cmd-通用模块定义-即时依赖" tabindex="-1">CMD 通用模块定义 - 即时依赖 <a class="header-anchor" href="#cmd-通用模块定义-即时依赖" aria-label="Permalink to &quot;CMD 通用模块定义 - 即时依赖&quot;">​</a></h1><ul><li><p>Common Module Defineion</p></li><li><p>2011左右，社区里面出现的一个标准</p></li><li><p>淘宝&quot;玉伯&quot;，开发一了个CMD的模块化标准</p></li><li><p>依赖于一个叫做sea.js的文件来实现的模块化标准</p></li><li><p>使用:文件需要引入一个sea.js的文件</p><ol><li>独立模块定义 <ul><li>define( function ( require, exports, module) { }) <ul><li>require() 用来导入其他文件的</li><li>module.exports是为了本文件导出内容的</li><li>exports是module. exports的别名</li><li>var exports = module。exports</li></ul></li></ul></li><li>依赖其他模块的模块 <ul><li>你需要依赖其他文件模块 <ul><li>在define( function ( require, exports, module) {</li><li>在你需要的位置使用require() 方法来导入</li><li>var modA = require( &#39;地址’)</li></ul></li></ul></li><li>资源整合 <ul><li>使用seajs.use()</li><li>语法: seajs.use([&#39;你要 依赖的模块&#39;]，function (模块A) {})</li></ul></li></ol></li><li><p>解决问题</p><ul><li>依赖前置</li><li>按需加载，在你需要的时候，在加载</li><li>也留下了依赖前置的接口</li></ul></li><li><p>问题:</p><ul><li>即时依赖 <ul><li>首屏加载快</li><li>操作不够流畅</li></ul></li></ul></li></ul><h1 id="es6-module-依赖前置" tabindex="-1">ES6 Module - 依赖前置 <a class="header-anchor" href="#es6-module-依赖前置" aria-label="Permalink to &quot;ES6 Module - 依赖前置&quot;">​</a></h1><ul><li>2015年发布，ES6 语法里面自带了一个模块化标准</li><li>各大浏览器厂商并不买账</li><li>2016年开始，Vue出现了，人家出现了一个脚手架(开发的大框架直接给你搭建好)</li><li>搭建这个架子的时候，内置了ES6模块化标准</li><li>2018 年，各大浏览器厂商开始原生支持ES6模块化标准</li><li>2018 年中，Chrome 率先原生支持ES6模块化</li><li>变成了JS的语法，和关键字，不需要任何第三方文件的引入 <ul><li>特点:页面必须在服务器上打开 <ul><li>live server 插件</li><li>如果你想使用模块化语法，script 标签要加一个属性type=&quot; module&quot;</li></ul></li></ul></li></ul><h2 id="语法" tabindex="-1">语法 <a class="header-anchor" href="#语法" aria-label="Permalink to &quot;语法&quot;">​</a></h2><ol><li>每一个文件都可以作为独立模块，页都可以作为整合文件</li><li>导出语法 <ol><li>export default 导出的内容</li><li>export var num = 200</li></ol></li><li>导入语法 <ol><li>接收export default 导出 <ul><li><code>import 变量 from&#39;哪一个JS文件&#39;</code></li></ul></li><li>接收export导出的那个 <ul><li><code>import {接收变量} from&#39; 哪-一个JS文件&#39;</code></li></ul></li></ol></li></ol><h1 id="es2020-发布新标准" tabindex="-1">ES2020 发布新标准 <a class="header-anchor" href="#es2020-发布新标准" aria-label="Permalink to &quot;ES2020 发布新标准&quot;">​</a></h1><ul><li>多了一个按需加载的模块化</li><li>语法: <code>import(你要加载的文件).then(function(res){})</code></li></ul>',16)]))}const h=i(u,[["render",r]]);export{m as __pageData,h as default};
